# A small map in the mapfile syntax of MapServer 8: areas, a river, roads, and places.
# Classes are picked by the features' properties, and the places are labelled with the font of
# fonts.lst, which the page hands to the bindings beside the mapfile.
MAP
  NAME "sample"
  EXTENT 0 0 100 60
  SIZE 640 400
  IMAGECOLOR "#f4f1ea"
  FONTSET "fonts.lst"

  SYMBOL
    NAME "circle"
    TYPE ELLIPSE
    FILLED TRUE
    POINTS 1 1 END
  END
  SYMBOL
    NAME "triangle"
    TYPE VECTOR
    FILLED TRUE
    POINTS 0 1 0.5 0 1 1 0 1 END
  END
  SYMBOL
    NAME "arrow"
    TYPE VECTOR
    POINTS 0 0 1 0.5 0 1 END
  END
  SYMBOL
    NAME "hatch"
    TYPE HATCH
  END

  LAYER
    NAME "areas"
    TYPE POLYGON
    STATUS ON
    DATA "areas.geojson"
    CLASSITEM "kind"
    CLASS
      NAME "park"
      EXPRESSION "park"
      STYLE
        COLOR 200 220 180
        OUTLINECOLOR 90 120 80
        WIDTH 1.5
      END
    END
    CLASS
      NAME "field"
      EXPRESSION "field"
      STYLE
        COLOR 236 222 170
        OUTLINECOLOR 170 150 90
        WIDTH 1
      END
    END
    CLASS
      NAME "wetland"
      EXPRESSION "wetland"
      STYLE
        COLOR 214 232 238
      END
      STYLE
        SYMBOL "hatch"
        COLOR 110 160 190
        SIZE 6
        WIDTH 1
        ANGLE 45
      END
      STYLE
        OUTLINECOLOR 110 160 190
        WIDTH 1
      END
    END
  END

  LAYER
    NAME "river"
    TYPE LINE
    STATUS ON
    DATA "river.geojson"
    COMPOSITE
      OPACITY 70
    END
    CLASS
      STYLE
        COLOR 90 150 210
        WIDTH 7
        LINECAP ROUND
        LINEJOIN ROUND
      END
    END
  END

  LAYER
    NAME "roads"
    TYPE LINE
    STATUS ON
    DATA "roads.geojson"
    CLASSITEM "kind"
    CLASS
      NAME "main road"
      EXPRESSION "main"
      STYLE
        COLOR 120 120 120
        WIDTH 6
      END
      STYLE
        COLOR 255 210 90
        WIDTH 3.5
      END
      STYLE
        SYMBOL "arrow"
        COLOR 150 110 20
        SIZE 7
        WIDTH 1
        GAP -60
        INITIALGAP 30
      END
    END
    CLASS
      NAME "side road"
      EXPRESSION "side"
      STYLE
        COLOR 120 120 120
        WIDTH 5
      END
      STYLE
        COLOR 255 255 255
        WIDTH 3
      END
    END
    CLASS
      NAME "trail"
      EXPRESSION "trail"
      STYLE
        COLOR 140 90 50
        WIDTH 1.5
        PATTERN 6 4 END
        LINECAP BUTT
      END
      STYLE
        SYMBOL "circle"
        GEOMTRANSFORM "start"
        COLOR 140 90 50
        SIZE 6
      END
      STYLE
        SYMBOL "circle"
        GEOMTRANSFORM "end"
        COLOR 140 90 50
        SIZE 6
      END
    END
  END

  LAYER
    NAME "places"
    TYPE POINT
    STATUS ON
    DATA "places.geojson"
    CLASSITEM "kind"
    LABELITEM "name"
    CLASS
      NAME "peak"
      EXPRESSION "peak"
      STYLE
        SYMBOL "triangle"
        COLOR 110 80 50
        SIZE [size]
      END
      LABEL
        FONT "sans"
        SIZE 9
        COLOR 80 60 40
        OUTLINECOLOR 255 255 255
        OUTLINEWIDTH 2
        POSITION UC
        OFFSET 0 -2
      END
    END
    CLASS
      NAME "settlement"
      STYLE
        SYMBOL "circle"
        COLOR 190 40 40
        OUTLINECOLOR 255 255 255
        SIZE [size]
        WIDTH 1.5
      END
      LABEL
        FONT "sans"
        SIZE 10
        COLOR 40 40 40
        OUTLINECOLOR 255 255 255
        OUTLINEWIDTH 2
        POSITION AUTO
        PRIORITY 5
      END
    END
  END
END
